// C++ program to count number of occurrences of a word in a text file
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    string line, word;
    int count = 0;

    ifstream myfile("filename.txt");
    if (myfile.is_open()) {
        while (getline(myfile, line)) {
            size_t pos = line.find(word);
            while (pos!= string::npos) {
                count++;
                pos = line.find(word, pos + 1);
            }
        }
        myfile.close();
    }
    else cout << "Unable to open file";
    return 0;
}assistantЎыџNЎыџN

